BEGIN;
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS device_sessions(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, replaced_by uuid);
CREATE TABLE IF NOT EXISTS workspace_bootstrap(workspace_id uuid PRIMARY KEY REFERENCES workspaces(id), secret_hash char(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), generation integer NOT NULL DEFAULT 1 CHECK(generation >= 1), rotated_at timestamptz);
CREATE TABLE IF NOT EXISTS pairing_codes(code_hash char(64) PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), expires_at timestamptz NOT NULL, consumed_at timestamptz, bootstrap_generation integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), project_id uuid REFERENCES projects(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversations(id), role text NOT NULL CHECK(role IN ('user','assistant','system','tool')), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS missions(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), project_id uuid REFERENCES projects(id), conversation_id uuid REFERENCES conversations(id), state text NOT NULL, trace_id text NOT NULL, idempotency_key text NOT NULL, request text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key));
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY, mission_id uuid NOT NULL REFERENCES missions(id), state text NOT NULL, attempt int NOT NULL DEFAULT 0 CHECK(attempt >= 0), max_attempts int NOT NULL DEFAULT 3 CHECK(max_attempts >= 1), lease_owner text, lease_expires_at double precision, fencing_token bigint NOT NULL DEFAULT 0, idempotency_key text NOT NULL, input_root text, output_root text, heartbeat_at double precision, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(mission_id,idempotency_key));
CREATE TABLE IF NOT EXISTS outbox_events(seq bigint GENERATED ALWAYS AS IDENTITY UNIQUE, event_id uuid PRIMARY KEY, event_type text NOT NULL, schema_version text NOT NULL, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, workspace_id uuid NOT NULL REFERENCES workspaces(id), correlation_id text NOT NULL, causation_id text, trace_id text NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL, published_at timestamptz, publish_attempts integer NOT NULL DEFAULT 0, last_publish_error text);
CREATE TABLE IF NOT EXISTS outbox_publication_receipts(consumer_id text NOT NULL, event_id uuid NOT NULL REFERENCES outbox_events(event_id), acknowledged_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE IF NOT EXISTS inbox_receipts(consumer_id text NOT NULL, event_id uuid NOT NULL, processed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE IF NOT EXISTS approvals(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), state text NOT NULL, actor text NOT NULL, action text NOT NULL, risk text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artifacts(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), mission_id uuid REFERENCES missions(id), sha256 char(64) NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes >= 0), storage_uri text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence_receipts(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), mission_id uuid REFERENCES missions(id), trace_id text NOT NULL, payload jsonb NOT NULL, sha256 char(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(seq bigint GENERATED ALWAYS AS IDENTITY UNIQUE, id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), actor text NOT NULL, action text NOT NULL, trace_id text NOT NULL, payload jsonb NOT NULL, prev_hash text NOT NULL, event_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_outbox_workspace_seq ON outbox_events(workspace_id, seq);
CREATE INDEX IF NOT EXISTS idx_outbox_unpublished ON outbox_events(seq) WHERE published_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_jobs_lease ON jobs(state, lease_expires_at);
CREATE INDEX IF NOT EXISTS idx_audit_workspace_seq ON audit_events(workspace_id, seq);
COMMIT;
